  <script>
    // === Menu ===
    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    // === Theme ===
    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    // === Data (from source_brief.md) ===
    var MODELS = [
      { name: 'Gemini 3.1 Pro Preview', intelligence: 57, speed: 129, price: 4.50 },
      { name: 'GPT-5.4 (xhigh)', intelligence: 57, speed: 72, price: 5.60 },
      { name: 'Claude Opus 4.6 (max)', intelligence: 53, speed: 40, price: 10.00 },
      { name: 'Claude Sonnet 4.6 (max)', intelligence: 52, speed: 48, price: 6.00 },
      { name: 'GLM-5.1', intelligence: 51, speed: 40, price: 2.10 },
      { name: 'Grok 4.20 0309 v2', intelligence: 49, speed: 162, price: 3.00 },
      { name: 'Gemini 3 Flash', intelligence: 46, speed: 149, price: 1.10 },
      { name: 'DeepSeek V3.2', intelligence: 42, speed: 31, price: 0.30 },
      { name: 'NVIDIA Nemotron 3 Super', intelligence: 36, speed: 193, price: 0.40 },
      { name: 'gpt-oss-120B (high)', intelligence: 33, speed: 206, price: 0.30 }
    ];

    function clamp(n, lo, hi) { return Math.max(lo, Math.min(hi, n)); }

    function getThemePalette() {
      var isDark = document.documentElement.classList.contains('theme-dark');
      return {
        isDark: isDark,
        text: isDark ? '#EDEDED' : '#0f172a',
        textSecondary: isDark ? '#9aa0a6' : '#64748b',
        grid: isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)',
        border: isDark ? 'rgba(255,255,255,0.10)' : 'rgba(0,0,0,0.10)',
        accent: isDark ? '#3b82f6' : '#2563eb',
        teal: isDark ? '#14b8a6' : '#0f766e',
        amber: isDark ? '#f59e0b' : '#d97706',
        violet: isDark ? '#8b5cf6' : '#7c3aed'
      };
    }

    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return null; }
        try {
          if (this.charts.has(canvasId)) {
            this.charts.get(canvasId).destroy();
            this.charts.delete(canvasId);
          }
          var canvas = document.getElementById(canvasId);
          if (!canvas) { console.error('Canvas not found:', canvasId); return null; }
          if (canvas.chart) { canvas.chart.destroy(); delete canvas.chart; }
          canvas.setAttribute('role', 'img');
          if (!canvas.getAttribute('aria-label')) canvas.setAttribute('aria-label', 'Chart visualization');
          var chart = new Chart(canvas.getContext('2d'), config);
          this.charts.set(canvasId, chart);
          canvas.chart = chart;
          return chart;
        } catch (e) {
          console.error('Chart init failed for', canvasId, e);
          return null;
        }
      },
      destroyAll: function() {
        this.charts.forEach(function(ch) { try { ch.destroy(); } catch(e){} });
        this.charts.clear();
      }
    };

    function fmtUsd(n) {
      return '$' + n.toFixed(2);
    }

    function buildCharts() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }

      var pal = getThemePalette();

      // Global defaults
      Chart.defaults.color = pal.textSecondary;
      Chart.defaults.font.family = 'Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif';
      Chart.defaults.plugins.tooltip.enabled = true;
      Chart.defaults.plugins.legend.labels.usePointStyle = true;
      Chart.defaults.plugins.legend.labels.pointStyle = 'circle';
      Chart.defaults.plugins.legend.labels.boxWidth = 10;
      Chart.defaults.plugins.legend.labels.color = pal.textSecondary;

      // ---- Trade-off (scatter bubble) ----
      var minPrice = Math.min.apply(null, MODELS.map(function(m){ return m.price; }));
      var maxPrice = Math.max.apply(null, MODELS.map(function(m){ return m.price; }));
      function radiusForPrice(price) {
        // area ~ price, keep in readable range
        var t = (price - minPrice) / (maxPrice - minPrice);
        var r = 10 + 34 * Math.sqrt(clamp(t, 0, 1));
        return r;
      }

      var leaders = new Set(['Gemini 3.1 Pro Preview', 'GPT-5.4 (xhigh)']);
      var balanced = new Set(['Gemini 3 Flash']);
      var speedChamp = new Set(['gpt-oss-120B (high)']);

      var bubbleData = MODELS.map(function(m) {
        var color = pal.textSecondary;
        if (leaders.has(m.name)) color = pal.accent;
        if (balanced.has(m.name)) color = pal.teal;
        if (speedChamp.has(m.name)) color = pal.amber;
        if (m.name === 'Claude Opus 4.6 (max)') color = pal.violet;

        return {
          x: m.speed,
          y: m.intelligence,
          r: radiusForPrice(m.price),
          _name: m.name,
          _price: m.price,
          _speed: m.speed,
          _intel: m.intelligence,
          _color: color
        };
      });

      ChartManager.safeInit('tradeoffChart', {
        type: 'bubble',
        data: {
          datasets: [{
            label: 'Models',
            data: bubbleData,
            parsing: false,
            backgroundColor: bubbleData.map(function(p){ return p._color.replace('#','').length === 6 ? hexToRgba(p._color, 0.30) : p._color; }),
            borderColor: bubbleData.map(function(p){ return hexToRgba(p._color, 0.85); }),
            borderWidth: 2,
            hoverBorderWidth: 3,
            hoverBackgroundColor: bubbleData.map(function(p){ return hexToRgba(p._color, 0.40); })
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          layout: { padding: { left: 14, right: 14, top: 12, bottom: 10 } },
          scales: {
            x: {
              title: { display: true, text: 'Output speed (tokens/sec)', color: pal.textSecondary, font: { size: 16, weight: 500 } },
              grid: { color: pal.grid },
              ticks: { color: pal.textSecondary, font: { size: 14 } },
              border: { color: pal.border },
              suggestedMin: 20,
              suggestedMax: 220
            },
            y: {
              title: { display: true, text: 'Intelligence (AA Index v4.0)', color: pal.textSecondary, font: { size: 16, weight: 500 } },
              grid: { color: pal.grid },
              ticks: { color: pal.textSecondary, font: { size: 14 } },
              border: { color: pal.border },
              suggestedMin: 30,
              suggestedMax: 60
            }
          },
          plugins: {
            legend: { display: false },
            tooltip: {
              enabled: true,
              callbacks: {
                label: function(ctx) {
                  var p = ctx.raw || {};
                  return p._name + ' — ' + p._intel + ' AA, ' + p._speed + ' tok/s, ' + fmtUsd(p._price) + ' /1M';
                }
              }
            }
          }
        }
      });

      // ---- Intelligence bar chart ----
      var intelSorted = MODELS.slice().sort(function(a,b){ return b.intelligence - a.intelligence; });
      ChartManager.safeInit('intelligenceChart', makeHorizontalBar({
        labels: intelSorted.map(function(m){ return m.name; }),
        values: intelSorted.map(function(m){ return m.intelligence; }),
        valueLabel: 'AA Index',
        colorFn: function(m){
          if (leaders.has(m.name)) return pal.accent;
          if (m.name === 'Claude Opus 4.6 (max)') return pal.violet;
          if (m.name === 'Gemini 3 Flash') return pal.teal;
          return pal.textSecondary;
        },
        items: intelSorted,
        pal: pal,
        max: 60
      }));

      // ---- Speed bar chart ----
      var speedSorted = MODELS.slice().sort(function(a,b){ return b.speed - a.speed; });
      ChartManager.safeInit('speedChart', makeHorizontalBar({
        labels: speedSorted.map(function(m){ return m.name; }),
        values: speedSorted.map(function(m){ return m.speed; }),
        valueLabel: 'tok/s',
        colorFn: function(m){
          if (speedChamp.has(m.name)) return pal.amber;
          if (m.name === 'NVIDIA Nemotron 3 Super') return pal.teal;
          if (m.name === 'Grok 4.20 0309 v2') return pal.violet;
          return pal.textSecondary;
        },
        items: speedSorted,
        pal: pal,
        max: 210
      }));

      // ---- Pricing bar chart (lower is better) ----
      var priceSorted = MODELS.slice().sort(function(a,b){ return a.price - b.price; });
      ChartManager.safeInit('priceChart', makeHorizontalBar({
        labels: priceSorted.map(function(m){ return m.name; }),
        values: priceSorted.map(function(m){ return m.price; }),
        valueLabel: '$ / 1M',
        items: priceSorted,
        pal: pal,
        max: 10,
        formatValue: function(v){ return '$' + v.toFixed(2); },
        colorFn: function(m){
          if (m.price <= 0.40) return pal.teal;
          if (m.price >= 6.00) return pal.amber;
          if (leaders.has(m.name)) return pal.accent;
          return pal.textSecondary;
        }
      }));
    }

    function makeHorizontalBar(opts) {
      var pal = opts.pal;
      var colors = opts.items.map(function(m){
        var c = opts.colorFn ? opts.colorFn(m) : pal.textSecondary;
        return hexToRgba(c, 0.38);
      });
      var borderColors = opts.items.map(function(m){
        var c = opts.colorFn ? opts.colorFn(m) : pal.textSecondary;
        return hexToRgba(c, 0.90);
      });

      return {
        type: 'bar',
        data: {
          labels: opts.labels,
          datasets: [{
            label: opts.valueLabel,
            data: opts.values,
            borderWidth: 1,
            borderRadius: 8,
            backgroundColor: colors,
            borderColor: borderColors,
            barThickness: 24,
            maxBarThickness: 26
          }]
        },
        options: {
          indexAxis: 'y',
          responsive: true,
          maintainAspectRatio: false,
          layout: { padding: { left: 22, right: 22, top: 12, bottom: 12 } },
          plugins: {
            legend: { display: false },
            tooltip: {
              enabled: true,
              callbacks: {
                label: function(ctx) {
                  var v = ctx.raw;
                  if (opts.formatValue) return opts.valueLabel + ': ' + opts.formatValue(v);
                  return opts.valueLabel + ': ' + v;
                }
              }
            }
          },
          scales: {
            x: {
              grid: { color: pal.grid },
              border: { color: pal.border },
              ticks: { color: pal.textSecondary, font: { size: 14 } },
              suggestedMin: 0,
              suggestedMax: opts.max
            },
            y: {
              grid: { display: false },
              border: { color: pal.border },
              ticks: {
                color: pal.text,
                font: { size: 14, weight: 500 },
                callback: function(v, idx) {
                  var label = (this.getLabelForValue ? this.getLabelForValue(v) : opts.labels[idx]) || '';
                  return label.length > 28 ? label.slice(0, 26) + '…' : label;
                }
              }
            }
          }
        }
      };
    }

    function hexToRgba(hex, alpha) {
      if (!hex || hex[0] !== '#') return hex;
      var h = hex.slice(1);
      if (h.length === 3) h = h.split('').map(function(c){ return c + c; }).join('');
      var r = parseInt(h.slice(0,2), 16);
      var g = parseInt(h.slice(2,4), 16);
      var b = parseInt(h.slice(4,6), 16);
      return 'rgba(' + r + ',' + g + ',' + b + ',' + alpha + ')';
    }

    var chartsBuilt = false;
    function buildOnce() {
      if (chartsBuilt) return;
      buildCharts();
      chartsBuilt = true;
    }

    function onThemeChange() {
      chartsBuilt = false;
      ChartManager.destroyAll();
      buildOnce();
    }

    window.addEventListener('load', function(){
      buildOnce();

      // Auto-render a poster PNG into /app/output/final_poster.png when run headless.
      // (If not headless, it just does nothing after charts build.)
      setTimeout(function(){
        if (typeof window.__EXPORT_POSTER__ === 'function') window.__EXPORT_POSTER__();
      }, 250);
    });

    // === Download PNG (required) ===
    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, {
          quality: 1,
          pixelRatio: 2,
          filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); }
        });
        var a = document.createElement('a');
        a.href = url;
        a.download = document.title.replace(/\s+/g, '-').toLowerCase() + '.png';
        a.click();
      } catch(e) {
        console.error('Download failed:', e);
      }
      menu.style.display = '';
    }
  </script>
</body>
